pre.code:
-- 查所有列
SELECT * FROM users;

-- 查指定列
SELECT name, age FROM users;

-- 条件查询（WHERE）
SELECT * FROM users WHERE city = '北京';

-- 多条件 AND
SELECT * FROM users WHERE city = '北京' AND age > 25;

-- 多条件 OR
SELECT * FROM users WHERE city = '北京' OR city = '上海';

-- IN（在列表中）
SELECT * FROM users WHERE city IN ('北京', '上海', '广州');

-- LIKE（模糊匹配，% 代表任意字符）
SELECT * FROM users WHERE name LIKE '张%';    -- 以"张"开头
SELECT * FROM users WHERE name LIKE '%三';    -- 以"三"结尾
SELECT * FROM users WHERE name LIKE '%三%';   -- 包含"三"

-- BETWEEN（范围）
SELECT * FROM users WHERE age BETWEEN 20 AND 30;

-- IS NULL / IS NOT NULL
SELECT * FROM users WHERE phone IS NULL;

-- 去重
SELECT DISTINCT city FROM users;

-- 升序排列
SELECT * FROM users ORDER BY age ASC;

-- 降序排列（-1 在 MongoDB 里表示降序，MySQL 用 DESC 关键字）
SELECT * FROM users ORDER BY age DESC;

-- 多字段排序：先按城市升序，同城市按年龄降序
SELECT * FROM users ORDER BY city ASC, age DESC;

-- 分页（LIMIT + OFFSET）
SELECT * FROM users ORDER BY id LIMIT 20;            -- 第 1 页，每页 20 条
SELECT * FROM users ORDER BY id LIMIT 20 OFFSET 20;  -- 第 2 页
SELECT * FROM users ORDER BY id LIMIT 20 OFFSET 40;  -- 第 3 页

-- 更新单条
UPDATE users SET age = 26 WHERE name = '张三';

-- 更新多条
UPDATE users SET status = 'inactive' WHERE city = '北京';

-- 同时更新多个字段
UPDATE users
SET age = 26, city = '深圳', updated_at = NOW()
WHERE name = '张三';

-- 数值自增
UPDATE users SET login_count = login_count + 1 WHERE name = '张三';

-- 删除指定行
DELETE FROM users WHERE name = '张三';

-- 删除多条
DELETE FROM users WHERE status = 'inactive';

-- 清空表（保留表结构，自增 ID 重置）
TRUNCATE TABLE users;

-- 清空表（逐行删除，不重置自增 ID）
DELETE FROM users;

-- 用户总数
SELECT COUNT(*) AS total_users FROM users;

-- 北京用户的平均年龄
SELECT AVG(age) AS avg_age FROM users WHERE city = '北京';

-- 总订单金额
SELECT SUM(amount) AS total_amount FROM orders;

-- 每天的新增用户数 SELECT DATE(created_at) AS day, COUNT(*) AS new_users FROM users GROUP BY DATE(created_at) ORDER BY day DESC;
-- 每个用户的订单总金额 SELECT user_id, SUM(amount) AS total_amount, COUNT(*) AS order_count FROM orders GROUP BY user_id ORDER BY total_amount DESC;
-- 每种状态的任务数量（DM 场景） SELECT status, COUNT(*) AS cnt FROM task_records GROUP BY status;
-- 每个 APP 的成功率 SELECT app_name, COUNT(*) AS total, SUM(CASE WHEN status = 'success' THEN 1 ELSE 0 END) AS success_count, SUM(CASE WHEN status = 'success' THEN 1 ELSE 0 END) / COUNT(*) * 100 AS success_rate FROM task_records GROUP BY app_name ORDER BY success_rate DESC;

-- 查用户和他们的任务（INNER JOIN） SELECT u.name, t.status FROM users u INNER JOIN task_records t ON u.id = t.user_id;
-- 查所有用户，有任务的显示任务状态，没任务的显示 NULL（LEFT JOIN） SELECT u.name, t.status FROM users u LEFT JOIN task_records t ON u.id = t.user_id;
-- 多表 JOIN SELECT u.name, t.status, a.app_name FROM users u INNER JOIN task_records t ON u.id = t.user_id INNER JOIN apps a ON t.app_id = a.id WHERE t.created_at > '2024-01-01';

-- WHERE 子查询：找出订单金额超过平均值的用户
SELECT name FROM users
WHERE id IN (
    SELECT user_id FROM orders
    WHERE amount > (SELECT AVG(amount) FROM orders)
);

-- FROM 子查询（派生表）
SELECT city, avg_age
FROM (
    SELECT city, AVG(age) AS avg_age
    FROM users
    GROUP BY city
) AS city_stats
WHERE avg_age > 30;

-- EXISTS 子查询：找出有任务记录的用户
SELECT name FROM users u
WHERE EXISTS (
    SELECT 1 FROM task_records t WHERE t.user_id = u.id
);

-- CASE WHEN（类似编程语言的 if-else） SELECT name, CASE WHEN age < 20 THEN '少年' WHEN age < 40 THEN '青年' WHEN age < 60 THEN '中年' ELSE '老年' END AS age_group FROM users;
-- IF（简单二选一） SELECT name, IF(age >= 18, '成年', '未成年') AS status FROM users;
-- IFNULL（处理 NULL 值） SELECT name, IFNULL(phone, '未填写') AS phone FROM users;
-- COALESCE（返回第一个非 NULL 值） SELECT COALESCE(phone, email, '无联系方式') AS contact FROM users;

-- 开始事务
START TRANSACTION;

-- 操作 1：A 扣 100
UPDATE accounts SET balance = balance - 100 WHERE user_id = 1;

-- 操作 2：B 加 100
UPDATE accounts SET balance = balance + 100 WHERE user_id = 2;

-- 确认没问题，提交
COMMIT;

-- 如果出错了，撤销所有操作
-- ROLLBACK;

-- 创建视图
CREATE VIEW active_beijing_users AS
SELECT name, age, phone
FROM users
WHERE city = '北京' AND status = 'active';

-- 使用视图（和查表一样）
SELECT * FROM active_beijing_users WHERE age > 25;

-- 删除视图
DROP VIEW active_beijing_users;

-- 创建存储过程
DELIMITER //
CREATE PROCEDURE GetUserStats(IN p_city VARCHAR(50))
BEGIN
    SELECT COUNT(*) AS total, AVG(age) AS avg_age
    FROM users WHERE city = p_city;
END //
DELIMITER ;

-- 调用
CALL GetUserStats('北京');

-- 创建表
CREATE TABLE users (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    age INT DEFAULT 0,
    city VARCHAR(50),
    status ENUM('active', 'inactive') DEFAULT 'active',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

-- 添加列
ALTER TABLE users ADD COLUMN phone VARCHAR(20);

-- 修改列类型
ALTER TABLE users MODIFY COLUMN age SMALLINT;

-- 重命名列
ALTER TABLE users RENAME COLUMN city TO location;

-- 删除列
ALTER TABLE users DROP COLUMN phone;

-- 查看表结构
DESCRIBE users;
SHOW CREATE TABLE users;

-- 删除表
DROP TABLE users;

-- 查看当前数据库
SELECT DATABASE();

-- 查看所有表
SHOW TABLES;

-- 查看表行数（近似值，很快）
SHOW TABLE STATUS LIKE 'users';

-- 精确行数（慢，大表慎用）
SELECT COUNT(*) FROM users;

-- 查看表索引
SHOW INDEX FROM users;

-- 查看当前连接
SHOW PROCESSLIST;

-- 杀掉某个连接
KILL process_id;

-- 查看表大小
SELECT
    table_name AS '表名',
    ROUND(data_length / 1024 / 1024, 2) AS '数据(MB)',
    ROUND(index_length / 1024 / 1024, 2) AS '索引(MB)',
    table_rows AS '行数'
FROM information_schema.tables
WHERE table_schema = 'your_database_name'
ORDER BY data_length DESC;
